import{_ as t,o as s,c as r,a3 as i}from"./chunks/framework.vNrIUzwY.js";const p=JSON.parse('{"title":"Design decisions","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/preview/docs-refresh/architecture/design-decisions.html"}],["meta",{"property":"og:title","content":"Design decisions | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/preview/docs-refresh/architecture/design-decisions.html"}],["meta",{"name":"twitter:title","content":"Design decisions | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"architecture/design-decisions.md","filePath":"architecture/design-decisions.md"}'),o={name:"architecture/design-decisions.md"};function n(a,e,c,l,d,h){return s(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="design-decisions" tabindex="-1">Design decisions <a class="header-anchor" href="#design-decisions" aria-label="Permalink to &quot;Design decisions&quot;">​</a></h1><ol><li><strong>Screen-space error LOD selection.</strong> Refine where a voxel covers more than <code>maxPixelError</code> pixels (default 8). One threshold adapts to resolution, field of view and distance.</li><li><strong>LRU eviction.</strong> Bricks are touched every frame they are desired; the least recently used one is evicted when the atlas is full, which keeps the current working set.</li><li><strong>Differential updates.</strong> Only missing bricks are loaded, so small camera moves cost few requests and uploads.</li><li><strong>Empty-brick skipping.</strong> The sharded index&#39;s statistics skip empty bricks before any request; OME-Zarr bricks found empty are never requested again. This pays off for CT with air around the object and microscopy with dark background.</li><li><strong>Coarse bricks fill many cells.</strong> A coarse brick writes its slot into every indirection cell it covers, and finer bricks overwrite theirs, so the shader always reads the finest loaded data without choosing a LOD itself.</li><li><strong>255 = empty.</strong> An explicit empty marker stops coarse data from showing through regions known to be empty at a finer level.</li><li><strong>66³ physical bricks.</strong> The one-voxel border lets hardware trilinear filtering work across brick edges with no special cases in the shader.</li><li><strong>Pinned base level.</strong> The coarsest level is loaded first and never evicted, so the whole volume is always visible at some resolution.</li><li><strong>Compute shader raymarching.</strong> The ray loop is one thread per pixel, equivalent to a fullscreen fragment shader, and uses no compute-only features yet. Compute makes the pipeline simpler: accumulation chains compute to compute, results go out with <code>textureStore</code>, and resolution scaling is a smaller dispatch instead of an intermediate framebuffer. It also leaves room for shared memory, subgroups and indirect dispatch. See <a href="/preview/docs-refresh/reference/webgpu.html">WebGPU notes</a>.</li></ol>',2)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
